export default function RoomCategoryIcons() {
  const [activeId, setActiveId] = useState<string>("living-room");

  return (
    <section className="w-full bg-white border-b border-slate-200 py-6 px-4 sm:px-8 lg:px-12 relative overflow-hidden">
      {/* Hidden SVG Gradient Definition */}
      <AnnouncementGradient />

      <div className="w-full mx-auto">
        {/* Full-width responsive grid across entire screen width */}
        <div className="grid grid-cols-3 sm:grid-cols-6 gap-3 sm:gap-6 w-full items-center justify-items-center">
          {ROOM_CATEGORIES.map((room) => {
            const isActive = activeId === room.id;
            return (
              <Link
                key={room.id}
                href={room.href}
                onMouseEnter={() => setActiveId(room.id)}
                className="group flex flex-col items-center justify-center w-full focus:outline-none"
              >
                {/* SVG Icon Container with exact Announcement Bar gradient hover */}
                <div
                  className={`transition-all duration-300 transform group-hover:scale-110 flex items-center justify-center ${
                    isActive
                      ? "[&_path]:fill-[url(#announcementGrad)] [&_circle]:fill-[url(#announcementGrad)] [&_rect]:fill-[url(#announcementGrad)] [&_g[stroke]]:stroke-[url(#announcementGrad)] text-[#5c249c]"
                      : "text-[#0d1b3e] group-hover:[&_path]:fill-[url(#announcementGrad)] group-hover:[&_circle]:fill-[url(#announcementGrad)] group-hover:[&_rect]:fill-[url(#announcementGrad)] group-hover:[&_g[stroke]]:stroke-[url(#announcementGrad)] group-hover:text-[#5c249c]"
                  }`}
                >
                  {room.svg}
                </div>

                {/* Text Label Below Icon */}
                <span
                  className={`mt-2.5 text-xs sm:text-sm md:text-base font-semibold tracking-wide text-center transition-all duration-300 ${
                    isActive
                      ? "bg-gradient-to-r from-[#2a1b92] via-[#5c249c] to-[#e91e63] bg-clip-text text-transparent font-bold"
                      : "text-slate-800 group-hover:bg-gradient-to-r group-hover:from-[#2a1b92] group-hover:via-[#5c249c] group-hover:to-[#e91e63] group-hover:bg-clip-text group-hover:text-transparent"
                  }`}
                >
                  {room.name}
                </span>
              </Link>
            );
          })}
        </div>
      </div>
    </section>
  );
}
